'use strict';
const CACHE_NAME='kaincheck-shell-6b702ccb5ea6';
const SHELL_FILES=['./','index.html','app.css','app.js','account.js','vendor/supabase.min.js','supabase-config.js','food-checker.js','pwa.js','personalization.js','manifest.webmanifest','icons/icon-192.png','icons/icon-512.png','icons/icon-maskable-512.png','icons/apple-touch-icon.png','install-qr.png'];
const SHELL_URLS=new Set(SHELL_FILES.map(path=>new URL(path,self.registration.scope).href));
async function isShellResponse(response,url){if(!response.ok||response.redirected||response.type==='opaque'||response.type==='opaqueredirect')return false;const actual=new URL(response.url||url);if(actual.origin!==self.location.origin)return false;const type=response.headers.get('content-type')||'';const path=new URL(url).pathname;if(path.endsWith('.js'))return /javascript/.test(type);if(path.endsWith('.css'))return /text\/css/.test(type);if(path.endsWith('.png'))return /image\/png/.test(type);if(path.endsWith('.webmanifest'))return /json|manifest/.test(type);if(!/text\/html/.test(type))return false;const html=await response.clone().text();return html.includes('<main class="stage">')&&html.includes('id="app"');}
self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(CACHE_NAME);await Promise.all(SHELL_FILES.map(async path=>{const url=new URL(path,self.registration.scope).href;const response=await fetch(url,{cache:'reload',credentials:'same-origin',redirect:'error'});if(!await isShellResponse(response,url))throw Error('App file unavailable: '+path);await cache.put(url,response);}));await self.skipWaiting();})());});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('kaincheck-shell-')&&key!==CACHE_NAME)await caches.delete(key);await self.clients.claim();})());});
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin)return;const shellUrl=url.origin+url.pathname;if(!SHELL_URLS.has(shellUrl))return;
 event.respondWith((async()=>{const cache=await caches.open(CACHE_NAME);try{const response=await fetch(request);if(await isShellResponse(response,shellUrl))await cache.put(shellUrl,response.clone());return response;}catch{const saved=await cache.match(shellUrl);if(saved)return saved;if(request.mode==='navigate'){const entry=await cache.match(new URL('index.html',self.registration.scope).href);if(entry)return entry;}return Response.error();}})());
});
